  size:(s,v)=>{ s.size=+v; return 'keep'; },
  addp:(s,v)=>{ const p=PR.find(x=>x.id===v), z=SIZES[s.size]; s.cart.push({id:v,size:z[0],price:Math.round(p.price*z[1]/10)*10,q:1,card:s.card}); s.page='cart'; s.step='cart'; return {toast:'Букет в корзине'}; },
  cq:(s,v)=>{ const [i,d]=v.split('|'); s.cart[+i].q=Math.max(0,s.cart[+i].q+ +d); s.cart=s.cart.filter(x=>x.q); return 'keep'; }, rm:(s,v)=>{ s.cart.splice(+v,1); return 'keep'; },
